package dev.trentdb.storage;import dev.trentdb.storage.format.*;import java.util.*;
public final class DuckDbRowGroupHeaderReader{private final DuckDbTableStatisticsReader stats;public DuckDbRowGroupHeaderReader(SingleFileBlockManager m,MetaBlockPointer p,List<DuckDbTableCreateInfo.ScalarLogicalType> t){stats=new DuckDbTableStatisticsReader(m,p,t);}public DuckDbRowGroupHeaders read(){var c=stats.readCursor();var r=c.reader();long n=r.readUnsignedLongLittleEndian();bound(n,"row group count");var g=new ArrayList<DuckDbRowGroupHeaders.Header>();for(int i=0;i<n;i++){r.beginObject();r.beginProperty(100);long start=r.readUnsignedLeb128();r.beginProperty(101);long count=r.readUnsignedLeb128();r.beginProperty(102);var data=pointers(r);r.beginProperty(103);var del=pointers(r);boolean hasMetadata=r.beginOptionalProperty(104)&&r.readBoolean();var extra=blocks(r,105,"row group extra metadata block count");boolean hasPerColumn=r.beginOptionalProperty(106)&&r.readBoolean();var perColumn=perColumnBlocks(r);if(hasPerColumn){hasMetadata=false;extra=List.of();}r.endObject();g.add(new DuckDbRowGroupHeaders.Header(start,count,data,del,hasMetadata,extra,hasPerColumn,perColumn));}return new DuckDbRowGroupHeaders(c.statistics(),g);}private List<DuckDbTableEntryEnvelope.MetaPointer> pointers(DuckDbBinaryMetadataReader r){long n=r.beginList();bound(n,"row group pointer count");var x=new ArrayList<DuckDbTableEntryEnvelope.MetaPointer>();for(int i=0;i<n;i++){r.beginObject();long p=r.beginOptionalProperty(100)?r.readUnsignedLeb128():0;long o=r.beginOptionalProperty(101)?r.readUnsignedLeb128():0;if(Long.compareUnsigned(o,0xffffffffL)>0)throw new StorageFormatException("DuckDB row group pointer offset exceeds uint32");r.endObject();x.add(new DuckDbTableEntryEnvelope.MetaPointer(p,o));}return x;}private List<Long> blocks(DuckDbBinaryMetadataReader r,int field,String name){if(!r.beginOptionalProperty(field))return List.of();long n=r.beginList();bound(n,name);var x=new ArrayList<Long>((int)n);for(int i=0;i<n;i++)x.add(r.readUnsignedLeb128());return x;}private List<DuckDbRowGroupHeaders.PerColumnMetadataBlock> perColumnBlocks(DuckDbBinaryMetadataReader r){if(!r.beginOptionalProperty(107))return List.of();long n=r.beginList();bound(n,"row group per-column metadata block count");var x=new ArrayList<DuckDbRowGroupHeaders.PerColumnMetadataBlock>((int)n);for(int i=0;i<n;i++){long packed=r.readUnsignedLeb128();x.add(new DuckDbRowGroupHeaders.PerColumnMetadataBlock((packed&Long.MIN_VALUE)!=0,packed&Long.MAX_VALUE));}return x;}private static void bound(long n,String name){if(Long.compareUnsigned(n,Integer.MAX_VALUE)>0)throw new StorageFormatException("DuckDB "+name+" exceeds supported bound");}}
